insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g4_tech_v1'
from (values
('126.9.c.4',3,'A drone that delivers packages or a car that drives itself are examples of...','["emerging technologies", "old tools", "toys only", "rocks"]'::jsonb,0,'Emerging technologies are new.','original'),
('126.9.c.4',4,'Virtual reality headsets and smart assistants are best described as...','["unchanging tools", "new, developing technologies", "fossils", "extinct tools"]'::jsonb,1,'They are emerging.','original'),
('126.9.c.6',4,'A spreadsheet can add up a column of numbers. This helps you transform data to answer a...','["riddle", "prize", "question", "cost"]'::jsonb,2,'Digital tools analyze data.','original'),
('126.9.c.6',4,'You sort survey results from smallest to largest in a spreadsheet and notice most students chose the middle value. This is making an...','["error", "echo", "erase", "inference"]'::jsonb,3,'Inferences come from data.','original'),
('126.9.c.7',3,'Presenting the results of your science experiment using slides to teach your class is using digital tools to communicate to your...','["intended audience", "desk", "clock", "shoe"]'::jsonb,0,'Match results to the audience.','original'),
('126.9.c.1.A',3,'Breaking a long word problem into small steps and writing down different ways to solve it is decomposing and...','["ignoring it", "documenting solutions", "giving up", "guessing"]'::jsonb,1,'Decompose and document.','original'),
('126.9.c.1.B',4,'A bus leaves at 8:00, 8:15, 8:30. You predict the next bus time is...','["10:00", "9:30", "8:45", "8:20"]'::jsonb,2,'The pattern adds 15 minutes.','original'),
('126.9.c.1.C',3,'Sharing your design with a drawing, a model or a short video gives you more ways to...','["lose your plan", "hide your plan", "forget your plan", "communicate your plan"]'::jsonb,3,'Use multiple options to communicate.','original'),
('126.9.c.1.D',4,'You test a program and it prints the wrong number. Looking through your steps to find and fix the mistake is...','["debugging", "decorating", "deleting", "doubling"]'::jsonb,0,'Debugging fixes errors.','original'),
('126.9.c.2.A',4,'A program uses ''points = points + 5'' each time a player scores. The program is using a variable to...','["erase the screen", "modify data", "draw a picture", "play music only"]'::jsonb,1,'Variables can change values.','original'),
('126.9.c.2.B',4,'A program that repeats a step 10 times and also checks ''if score is above 50'' uses a loop and a...','["rest", "noun", "conditional", "comment"]'::jsonb,2,'Loops and conditionals control flow.','original'),
('126.9.c.2.B',4,'A program''s blocks that run one after another, top to bottom, form a...','["loop", "variable", "bug", "sequence"]'::jsonb,3,'A sequence is ordered steps.','original'),
('126.9.c.3.A',4,'Asking good questions, communicating well and thinking about your own learning are personal skills that help you carry out a...','["design process", "recess", "snack", "nap"]'::jsonb,0,'Design needs good habits.','original'),
('126.9.c.3.B',4,'After your team tests a model and finds a weak part, you improve and refine your product. This is part of a...','["nap", "design process", "snack", "recess"]'::jsonb,1,'Refine and improve.','original'),
('126.9.c.5.A',3,'A table lists each student''s favorite sport. This kind of data is classified as...','["measured", "counted", "non-numerical", "numerical"]'::jsonb,2,'Favorite sports are categories, not numbers.','original'),
('126.9.c.5.A',3,'You record how many minutes each student reads. Minutes are classified as...','["non-numerical data", "names", "categories", "numerical data"]'::jsonb,3,'Minutes are numbers.','original'),
('126.9.c.5.B',4,'Searching with two keywords like ''Texas bluebonnet history'' in a search engine usually gives...','["more focused results", "random pictures only", "fewer links to read", "no results"]'::jsonb,0,'More keywords narrow a search.','original'),
('126.9.c.8.A',3,'Things you post or search online can stay stored for a long time, creating a permanent digital...','["footnote", "footprint", "foot", "footstep"]'::jsonb,1,'Digital footprints last.','original'),
('126.9.c.8.B',3,'In an email to your teacher, appropriate digital etiquette is to use...','["slang with no greeting", "all capital letters", "a polite greeting and clear message", "rude jokes"]'::jsonb,2,'Be respectful.','original'),
('126.9.c.8.C',3,'During a video conference, a polite behavior is to...','["leave the room without a word", "turn music up", "talk over others", "mute yourself when not speaking"]'::jsonb,3,'Courteous collaboration.','original'),
('126.9.c.9.A',3,'Following the AUP and using devices responsibly is important because it shows...','["ethical technology use", "careless play", "no rules", "bad choices"]'::jsonb,0,'Responsible use matters.','original'),
('126.9.c.9.B',4,'A creator who makes a song or picture has rights. Copyright law helps protect those...','["lunch rights", "rights of the creator", "travel rights", "rights of the thief"]'::jsonb,1,'Copyright protects creators.','original'),
('126.9.c.9.B',4,'You can use a copyrighted picture in a school report most correctly if you...','["sell copies", "remove the artist''s name", "give credit and follow the usage rules", "claim it is yours"]'::jsonb,2,'Cite and follow rules.','original'),
('126.9.c.9.C',4,'A citation for a website should list the author, the title and the...','["favorite color", "lunch", "weather", "date and address of the site"]'::jsonb,3,'Citations track sources.','original'),
('126.9.c.10.A',3,'A strong password and logging off devices matter because they...','["protect your account from strangers", "slow the computer", "erase your files", "waste time"]'::jsonb,0,'Security protects accounts.','original'),
('126.9.c.10.B',4,'Small files that websites store on your device to track what you do are called...','["candies", "cookies", "crumbs", "coupons"]'::jsonb,1,'Cookies track activity.','original'),
('126.9.c.10.B',4,'A pop-up that asks for your personal information may be an attempt to collect...','["a lunch", "a pencil", "your private data", "a free toy"]'::jsonb,2,'Be careful with pop-ups.','original'),
('126.9.c.10.B',4,'Using an unsecured public Wi-Fi network without protection can put your information at...','["ease", "speed", "rest", "risk"]'::jsonb,3,'Unsecured networks are risky.','original'),
('126.9.c.10.C',4,'Standing up for a classmate who is being cyberbullied by telling a trusted adult is called...','["advocating for others", "ignoring problems", "hiding", "joining in"]'::jsonb,0,'Advocacy is speaking up.','original'),
('126.9.c.10.C',3,'If you are cyberbullied, one good response is to save the messages and...','["reply with insults", "report it to a trusted adult", "delete everything silently", "post them everywhere"]'::jsonb,1,'Report it.','original'),
('126.9.c.11.A',4,'For a task that needs a pie chart from numbers, the most relevant application is a...','["calendar only", "word processor only", "spreadsheet", "notepad only"]'::jsonb,2,'Spreadsheets make charts.','original'),
('126.9.c.11.B',3,'Creating a list with dots in front of each item is called...','["rotating", "erasing", "footnoting", "bulleting"]'::jsonb,3,'Bullets create lists.','original'),
('126.9.c.11.B',4,'The ''find and replace'' tool in a word processor lets you...','["change every instance of a word at once", "mail letters", "draw pictures", "play videos"]'::jsonb,0,'Find and replace edits quickly.','original'),
('126.9.c.12.A',4,'A computer-generated 3D world you explore with a headset is...','["a book", "virtual reality", "a paper map", "a chalkboard"]'::jsonb,1,'VR immerses you.','original'),
('126.9.c.12.A',4,'A tool that puts digital pictures on top of the real world on your tablet''s camera is...','["a map", "a calculator", "augmented reality", "a pencil"]'::jsonb,2,'AR overlays.','original'),
('126.9.c.12.B',3,'Naming a file with a clear name and putting it in the correct folder is good...','["decoration", "dancing", "noise", "file management"]'::jsonb,3,'File management helps you find things.','original'),
('126.9.c.12.B',4,'Which folder structure is most organized for science work?','["Science > Plants > Photosynthesis report", "Folder1 > New", "Stuff > Misc > Doc", "Desktop > Untitled"]'::jsonb,0,'Clear structures help organization.','original'),
('126.9.c.12.C',3,'Typing with speed and accuracy while sitting with a straight back and relaxed wrists is proper...','["doodling", "touch keyboarding", "stretching", "dancing"]'::jsonb,1,'Ergonomic typing.','original'),
('126.9.c.12.D',4,'On many keyboards, pressing Shift and a number key types a...','["space", "number", "symbol", "tab"]'::jsonb,2,'Secondary symbols.','original'),
('126.9.c.12.D',4,'To paste text you copied, press...','["Control and Q", "Control and P", "Shift and Tab", "Control (or Command) and V"]'::jsonb,3,'Paste is Ctrl+V.','original'),
('126.9.c.12.E',4,'When a program stops responding, a basic troubleshooting step is to...','["restart the program", "spill water", "throw the computer", "ignore it"]'::jsonb,0,'Restart first.','original'),
('126.9.c.12.E',4,'If your tablet will not respond to touches, you can try...','["painting it", "rebooting the device", "burying it", "shaking it hard"]'::jsonb,1,'Reboot hardware.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Technology Applications' and d.language = 'en'
on conflict (fingerprint) do nothing;
